        if (((((p.text[@as(usize, @intCast((off + 1)))] == 33) and ((off + 2) < p.size)) and (p.text[@as(usize, @intCast((off + 2)))] >= 65)) and (p.text[@as(usize, @intCast((off + 2)))] <= 90))) {
